//! TypeScript の型定義の書き出し (仕様 §23、issue #197)
//!
//! 名前空間 `a.b` ごとにファイル `a.b.ts` を作り、record を interface、enum を文字列リテラルの union にする。
//! 値は辞書の表し方 (仕様 §4) のまま扱う (管理画面・`bindings/js` が JSON で受け渡す値の型)。
//! 型ごとに型参照 `<型名>Type` (`{name, fingerprint, avro}`) も書く。共通の定義は `juiz_idl.ts`。
//! 実行時のライブラリには依存しない。

use std::collections::{BTreeMap, BTreeSet};

use juiz_types::DataType;
use serde_json::Value;

use crate::constants::record_constants;
use crate::{GeneratedFile, IdlError};

const HEADER: &str =
    "// @generated by juiz-idl. 手で直さないこと (元の .jidl / .avsc を直して作り直す)\n";

/// 名前空間をまたがない共通の定義
pub const TYPESCRIPT_COMMON_FILE: &str = "juiz_idl.ts";

/// 型の名前に使えない名前 (TypeScript の予約語と組み込みの型、生成したコードが使う名前)
const RESERVED: [&str; 52] = [
    "any",
    "bigint",
    "boolean",
    "never",
    "null",
    "number",
    "object",
    "string",
    "symbol",
    "undefined",
    "unknown",
    "void",
    "Array",
    "Record",
    "Readonly",
    "TypeSchema",
    "break",
    "case",
    "catch",
    "class",
    "const",
    "continue",
    "debugger",
    "default",
    "delete",
    "do",
    "else",
    "enum",
    "export",
    "extends",
    "false",
    "finally",
    "for",
    "function",
    "if",
    "import",
    "in",
    "instanceof",
    "new",
    "return",
    "super",
    "switch",
    "this",
    "throw",
    "true",
    "try",
    "typeof",
    "var",
    "while",
    "with",
    "type",
    "interface",
];

fn generate_error(message: String) -> IdlError {
    IdlError::Generate { message }
}

fn named(t: &DataType) -> (&str, &str) {
    match t {
        DataType::Record(r) => (&r.namespace, &r.name),
        DataType::Enum(e) => (&e.namespace, &e.name),
        _ => unreachable!(),
    }
}

fn full_name(t: &DataType) -> String {
    let (ns, name) = named(t);
    format!("{ns}.{name}")
}

/// 名前空間 `a.b` の型を別の名前空間から使うときの import の別名 (`a_b`)
fn import_alias(ns: &str) -> String {
    ns.replace('.', "_")
}

/// 型の TypeScript の表記。`ns` は今書いているファイルの名前空間
fn ts_type(t: &DataType, ns: &str) -> Result<String, IdlError> {
    Ok(match t {
        DataType::Null => "null".to_owned(),
        DataType::Boolean => "boolean".to_owned(),
        // long も number (2^53 を超える値は精度が落ちる、仕様 §23)
        DataType::Int | DataType::Long | DataType::Float | DataType::Double => "number".to_owned(),
        DataType::String => "string".to_owned(),
        // 辞書では base64 の文字列 (仕様 §4)
        DataType::Bytes => "string".to_owned(),
        DataType::Array(items) => {
            let inner = ts_type(items, ns)?;
            if inner.contains(' ') {
                format!("({inner})[]")
            } else {
                format!("{inner}[]")
            }
        }
        DataType::Map(values) => format!("Record<string, {}>", ts_type(values, ns)?),
        DataType::Optional { inner, .. } => format!("{} | null", ts_type(inner, ns)?),
        DataType::Record(_) | DataType::Enum(_) => {
            let (tns, name) = named(t);
            if tns == ns {
                name.to_owned()
            } else {
                format!("{}.{name}", import_alias(tns))
            }
        }
        DataType::Any => "unknown".to_owned(),
        DataType::Image => {
            return Err(generate_error(
                "image cannot be used inside a record (spec §3.3)".to_owned(),
            ))
        }
    })
}

/// 型が参照する名前付き型 (入れ子の record の中には入らない)
fn collect_refs<'a>(t: &'a DataType, out: &mut Vec<&'a DataType>) {
    match t {
        DataType::Array(i) | DataType::Map(i) => collect_refs(i, out),
        DataType::Optional { inner, .. } => collect_refs(inner, out),
        DataType::Record(_) | DataType::Enum(_) => out.push(t),
        _ => {}
    }
}

/// TSDoc のコメント
fn doc_lines(doc: &Option<String>, pad: &str) -> String {
    match doc {
        Some(d) => {
            let d = d.replace("*/", "*\\/");
            let lines: Vec<&str> = d.lines().collect();
            if lines.len() == 1 {
                format!("{pad}/** {} */\n", lines[0])
            } else {
                let mut out = format!("{pad}/**\n");
                for l in lines.iter() {
                    out.push_str(&format!(
                        "{pad} *{}{l}\n",
                        if l.is_empty() { "" } else { " " }
                    ));
                }
                out.push_str(&format!("{pad} */\n"));
                out
            }
        }
        None => String::new(),
    }
}

/// JSON の値を TypeScript の式にする (インデントは付けない)
fn json_literal(v: &Value) -> String {
    serde_json::to_string(v).unwrap()
}

/// 名前付き型 (record・enum) の TypeScript の型定義。名前空間ごとに 1 ファイルと `juiz_idl.ts`
pub fn generate_typescript(types: &[DataType]) -> Result<Vec<GeneratedFile>, IdlError> {
    let mut by_namespace: BTreeMap<String, Vec<&DataType>> = BTreeMap::new();
    for t in types.iter() {
        if matches!(t, DataType::Record(_) | DataType::Enum(_)) {
            let (ns, _) = named(t);
            if ns.is_empty() {
                return Err(generate_error(format!(
                    "type '{}' has no namespace; TypeScript code needs a namespace",
                    t.display_name()
                )));
            }
            by_namespace.entry(ns.to_owned()).or_default().push(t);
        }
    }
    let mut files = vec![GeneratedFile {
        path: TYPESCRIPT_COMMON_FILE.into(),
        contents: format!(
            "{HEADER}\n\
             /** 型参照 (仕様 §6)。`avro` はそれだけで完結した Avro のスキーマ */\n\
             export interface TypeSchema {{\n  \
             readonly name: string;\n  \
             readonly fingerprint: string;\n  \
             readonly avro: unknown;\n\
             }}\n"
        ),
    }];
    let mut aliases = BTreeMap::new();
    for ns in by_namespace.keys() {
        if let Some(other) = aliases.insert(import_alias(ns), ns.clone()) {
            return Err(generate_error(format!(
                "namespaces '{other}' and '{ns}' both become the TypeScript import name '{}'",
                import_alias(ns)
            )));
        }
    }
    for (ns, ts) in by_namespace.iter() {
        files.push(GeneratedFile {
            path: format!("{ns}.ts").into(),
            contents: file_code(ns, ts)?,
        });
    }
    Ok(files)
}

fn file_code(ns: &str, ts: &[&DataType]) -> Result<String, IdlError> {
    // ファイルの中の名前 (型と値は別の名前空間)
    let mut type_names: BTreeMap<String, String> = BTreeMap::new();
    let mut value_names: BTreeMap<String, String> = BTreeMap::new();
    let add =
        |map: &mut BTreeMap<String, String>, name: &str, owner: &str| -> Result<(), IdlError> {
            if RESERVED.contains(&name) {
                return Err(generate_error(format!(
                    "{owner} becomes the TypeScript name '{name}', which is reserved"
                )));
            }
            if let Some(prev) = map.insert(name.to_owned(), owner.to_owned()) {
                return Err(generate_error(format!(
                    "{prev} and {owner} both become the TypeScript name '{name}'"
                )));
            }
            Ok(())
        };
    let mut deps = BTreeSet::new();
    let mut body = String::new();
    for t in ts.iter() {
        let (_, tn) = named(t);
        let full = full_name(t);
        add(&mut type_names, tn, &format!("type {full}"))?;
        let info = format!("{tn}Type");
        add(
            &mut value_names,
            &info,
            &format!("the type information of {full}"),
        )?;
        body.push('\n');
        match t {
            DataType::Record(r) => {
                body.push_str(&doc_lines(&r.doc, ""));
                body.push_str(&format!("export interface {tn} {{\n"));
                for f in r.fields.iter() {
                    let mut refs = Vec::new();
                    collect_refs(&f.data_type, &mut refs);
                    for d in refs.iter() {
                        if named(d).0 != ns {
                            deps.insert(named(d).0.to_owned());
                        }
                    }
                    body.push_str(&doc_lines(&f.doc, "  "));
                    body.push_str(&format!("  {}: {};\n", f.name, ts_type(&f.data_type, ns)?));
                }
                body.push_str("}\n");
                if r.fields.iter().all(|f| f.default.is_some()) {
                    let default_name = format!("default{tn}");
                    add(
                        &mut value_names,
                        &default_name,
                        &format!("the default value of {full}"),
                    )?;
                    body.push_str(&format!(
                        "\n/** すべてのフィールドが既定値の {tn} */\nexport function {default_name}(): {tn} {{\n  return {{\n"
                    ));
                    for f in r.fields.iter() {
                        let d = f.default_as_dict().unwrap_or(Value::Null);
                        body.push_str(&format!("    {}: {},\n", f.name, json_literal(&d)));
                    }
                    body.push_str("  };\n}\n");
                }
                // 定数 (juiz.constants、仕様 §25)
                let constants = record_constants(r).map_err(|m| IdlError::Generate {
                    message: format!("{full}: {m}"),
                })?;
                if !constants.is_empty() {
                    let cname = format!("{tn}Constants");
                    add(
                        &mut value_names,
                        &cname,
                        &format!("the constants of {full}"),
                    )?;
                    body.push_str(&format!(
                        "\n/** {tn} の定数 */\nexport const {cname} = {{\n"
                    ));
                    for c in constants.iter() {
                        body.push_str(&doc_lines(&c.doc, "  "));
                        body.push_str(&format!("  {}: {},\n", c.name, json_literal(&c.value)));
                    }
                    body.push_str("} as const;\n");
                }
            }
            DataType::Enum(e) => {
                body.push_str(&doc_lines(&e.doc, ""));
                let union = e
                    .symbols
                    .iter()
                    .map(|s| json_literal(&Value::from(s.as_str())))
                    .collect::<Vec<_>>();
                body.push_str(&format!("export type {tn} = {};\n", union.join(" | ")));
                let symbols = format!("{tn}Symbols");
                add(
                    &mut value_names,
                    &symbols,
                    &format!("the symbols of {full}"),
                )?;
                body.push_str(&format!(
                    "\n/** {tn} の記号 (宣言の順) */\nexport const {symbols}: readonly {tn}[] = [{}];\n",
                    union.join(", ")
                ));
            }
            _ => unreachable!(),
        }
        let avro = t
            .to_avro()
            .map_err(|e| generate_error(format!("{full}: {e}")))?;
        body.push_str(&format!(
            "\n/** {full} の型参照 */\nexport const {info}: TypeSchema = {{\n  name: {},\n  fingerprint: {},\n  avro: {},\n}};\n",
            json_literal(&Value::from(full.as_str())),
            json_literal(&Value::from(t.fingerprint())),
            json_literal(&avro),
        ));
    }
    let mut out = String::from(HEADER);
    out.push('\n');
    out.push_str(&format!(
        "import type {{ TypeSchema }} from \"./{}\";\n",
        TYPESCRIPT_COMMON_FILE.replace(".ts", ".js")
    ));
    for d in deps.iter() {
        out.push_str(&format!(
            "import type * as {} from \"./{d}.js\";\n",
            import_alias(d)
        ));
        if type_names.contains_key(&import_alias(d)) || value_names.contains_key(&import_alias(d)) {
            return Err(generate_error(format!(
                "the import name '{}' of namespace '{d}' is also a name in namespace '{ns}'",
                import_alias(d)
            )));
        }
    }
    out.push_str(&body);
    Ok(out)
}
